CREATE TABLE "HistoryArchiveBatch" (id TEXT PRIMARY KEY, "actorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "restoredAt" TIMESTAMP(3), "restoredBy" TEXT, "backupSha256" TEXT NOT NULL, counts JSONB NOT NULL DEFAULT '{}');
CREATE TABLE "HistoryArchiveItem" ("batchId" TEXT NOT NULL REFERENCES "HistoryArchiveBatch"(id) ON DELETE RESTRICT, entity TEXT NOT NULL, "recordId" TEXT NOT NULL, "previousStatus" TEXT, PRIMARY KEY("batchId",entity,"recordId"));
CREATE INDEX "HistoryArchiveItem_lookup" ON "HistoryArchiveItem"(entity,"recordId");
CREATE SCHEMA history_display;
CREATE FUNCTION history_display.is_archived(entity_name TEXT, record_id TEXT) RETURNS BOOLEAN LANGUAGE SQL STABLE COST 1 AS $$ SELECT EXISTS (SELECT 1 FROM public."HistoryArchiveItem" i JOIN public."HistoryArchiveBatch" b ON b.id=i."batchId" WHERE i.entity=entity_name AND i."recordId"=record_id AND b."restoredAt" IS NULL) $$;
CREATE TYPE history_display."Role" AS ENUM ('ADMIN', 'SALES');
CREATE TYPE history_display."Platform" AS ENUM ('XHS', 'DOUYIN');
CREATE TYPE history_display."LeadStatus" AS ENUM ('PENDING_REVIEW', 'FOLLOWING', 'CLOSED');
CREATE TYPE history_display."ContactStage" AS ENUM ('MATCHED', 'TO_CONTACT', 'CONTACTED', 'INTERESTED', 'IGNORED');
CREATE TYPE history_display."TaskStatus" AS ENUM ('PENDING', 'DONE', 'PAUSED');
CREATE TYPE history_display."AccountStatus" AS ENUM ('UNCONNECTED', 'RESTRICTED', 'PAUSED');
CREATE TYPE history_display."ReplyChannel" AS ENUM ('COMMENT', 'DM');
CREATE TYPE history_display."ContactOutcome" AS ENUM ('RESERVED', 'CONFIRMED', 'CANCELLED', 'ATTEMPTED', 'UNKNOWN', 'SIMULATED_SUCCESS', 'FAILED');
CREATE VIEW history_display."CollectionRun" AS SELECT t.* FROM public."CollectionRun" t WHERE NOT history_display.is_archived('CollectionRun',t.id);
CREATE VIEW history_display."CapturedPost" AS SELECT t.* FROM public."CapturedPost" t WHERE NOT history_display.is_archived('CapturedPost',t.id) OR EXISTS (SELECT 1 FROM public."CollectionRun" r WHERE r.id=t."lastRunId" AND NOT history_display.is_archived('CollectionRun',r.id));
CREATE VIEW history_display."CapturedComment" AS SELECT t.* FROM public."CapturedComment" t WHERE NOT history_display.is_archived('CapturedComment',t.id) OR EXISTS (SELECT 1 FROM public."CollectionRun" r WHERE r.id=t."lastRunId" AND NOT history_display.is_archived('CollectionRun',r.id));
CREATE VIEW history_display."SemanticReview" AS SELECT t."policyId",t."policyRevision",t."sourceContentHash",t."analysisKey",t."selectedModel",t."ruleHash",t."contextVersion",t."captureId",t."evaluationInput",t."id",t."configId",t."runId",t."revision",t."leaseUntil",t."snapshotHash",t."platform"::text::history_display."Platform" AS "platform",t."platformUserId",t."snapshot",t."rules",t."state",t."score",t."reason",t."context",t."result",t."provider",t."modelVersion",t."isDemo",t."reviewStatus",t."reviewNote",t."reviewedBy",t."reviewedAt",t."version",t."createdAt",t."updatedAt" FROM public."SemanticReview" t WHERE NOT history_display.is_archived('SemanticReview',t.id) OR EXISTS (SELECT 1 FROM public."CapturedComment" c WHERE c.id=t."captureId" AND (NOT history_display.is_archived('CapturedComment',c.id) OR EXISTS (SELECT 1 FROM public."CollectionRun" r WHERE r.id=c."lastRunId" AND NOT history_display.is_archived('CollectionRun',r.id))));
CREATE VIEW history_display."User" AS SELECT t."id",t."email",t."name",t."passwordHash",t."role"::text::history_display."Role" AS "role",t."active",t."createdAt" FROM public."User" t;
CREATE VIEW history_display."Session" AS SELECT * FROM public."Session";
CREATE VIEW history_display."RefreshGrant" AS SELECT * FROM public."RefreshGrant";
CREATE VIEW history_display."RefreshToken" AS SELECT * FROM public."RefreshToken";
CREATE VIEW history_display."LoginBucket" AS SELECT * FROM public."LoginBucket";
CREATE VIEW history_display."PlatformAccount" AS SELECT t."id",t."platform"::text::history_display."Platform" AS "platform",t."label",t."status"::text::history_display."AccountStatus" AS "status",t."isDemo",t."pauseReason",t."ownerId",t."dailyLimit",t."archivedAt",t."version",t."loginSessionKey",t."loginProvider",t."loginPlatformUserId",t."loginNickname",t."loginVerifiedAt",t."createdAt" FROM public."PlatformAccount" t;
CREATE VIEW history_display."PlatformIdentity" AS SELECT t."id",t."platform"::text::history_display."Platform" AS "platform",t."platformUserId",t."nickname",t."isDemo" FROM public."PlatformIdentity" t;
CREATE VIEW history_display."SourcePost" AS SELECT t."id",t."platform"::text::history_display."Platform" AS "platform",t."platformPostId",t."title",t."isDemo" FROM public."SourcePost" t WHERE NOT history_display.is_archived('SourcePost',t.id);
CREATE VIEW history_display."SourceComment" AS SELECT t."id",t."platform"::text::history_display."Platform" AS "platform",t."platformCommentId",t."postId",t."identityId",t."parentPlatformCommentId",t."originalText",t."observedAt",t."isDemo" FROM public."SourceComment" t WHERE NOT history_display.is_archived('SourceComment',t.id);
CREATE VIEW history_display."Lead" AS SELECT t."id",t."identityId",t."summary",t."evidence",t."status"::text::history_display."LeadStatus" AS "status",t."contactStage"::text::history_display."ContactStage" AS "contactStage",t."doNotContact",t."contactNote",t."contactedAt",t."ownerId",t."reviewedAt",t."reviewNote",t."nextFollowUpAt",t."isDemo",t."version",t."createdAt",t."updatedAt" FROM public."Lead" t;
CREATE VIEW history_display."FollowUp" AS SELECT * FROM public."FollowUp";
CREATE VIEW history_display."Task" AS SELECT t."id",t."leadId",t."title",t."kind",t."status"::text::history_display."TaskStatus" AS "status",t."dueAt",t."createdAt",t."updatedAt" FROM public."Task" t;
CREATE VIEW history_display."AuditLog" AS SELECT * FROM public."AuditLog";
CREATE VIEW history_display."ReplyTemplate" AS SELECT t."id",t."name",t."channel"::text::history_display."ReplyChannel" AS "channel",t."body",t."version",t."createdAt",t."updatedAt" FROM public."ReplyTemplate" t;
CREATE VIEW history_display."CollectionConfig" AS SELECT t."defaultExecutionAccountId",t."legacyMatchingEnabled",t."semanticRules",t."commentRules",t."defaultReplyTemplateId",t."id",t."name",t."platform"::text::history_display."Platform" AS "platform",t."mode",t."keywords",t."excludeWords",t."batchLimit",t."enabled",t."revision",t."activeRunId",t."failureCount",t."nextAllowedAt",t."pauseReason",t."archivedAt",t."createdAt",t."updatedAt" FROM public."CollectionConfig" t;
CREATE VIEW history_display."MonitorPost" AS SELECT t.* FROM public."MonitorPost" t WHERE NOT history_display.is_archived('MonitorPost',t.id);
CREATE VIEW history_display."CommentObservation" AS SELECT t.* FROM public."CommentObservation" t WHERE NOT history_display.is_archived('CommentObservation',t.id);
CREATE VIEW history_display."SourceMatch" AS SELECT t.* FROM public."SourceMatch" t WHERE NOT history_display.is_archived('SourceMatch',t.id);
CREATE VIEW history_display."CollectionNotice" AS SELECT t.* FROM public."CollectionNotice" t WHERE NOT history_display.is_archived('CollectionNotice',t.id);
CREATE VIEW history_display."NoticeRead" AS SELECT n.* FROM public."NoticeRead" n JOIN history_display."CollectionNotice" c ON c.id=n."noticeId";
CREATE VIEW history_display."AccountDay" AS SELECT * FROM public."AccountDay";
CREATE VIEW history_display."ContactLedger" AS SELECT * FROM public."ContactLedger";
CREATE VIEW history_display."ContactAttempt" AS SELECT t."accountIdSnapshot",t."historySnapshot",t."jobId",t."mode",t."channel"::text::history_display."ReplyChannel" AS "channel",t."content",t."platformReceipt",t."attemptedAt",t."confirmedAt",t."id",t."ledgerId",t."requestKey",t."kind",t."outcome"::text::history_display."ContactOutcome" AS "outcome",t."day",t."actorId",t."resolutionNote",t."version",t."createdAt",t."updatedAt" FROM public."ContactAttempt" t WHERE NOT history_display.is_archived('ContactAttempt',t.id);
CREATE VIEW history_display."AccountLogin" AS SELECT * FROM public."AccountLogin";
CREATE VIEW history_display."AccountSessionReference" AS SELECT * FROM public."AccountSessionReference";
CREATE VIEW history_display."ExecutionDevice" AS SELECT * FROM public."ExecutionDevice";
CREATE VIEW history_display."DeviceExecutionLease" AS SELECT * FROM public."DeviceExecutionLease";
CREATE VIEW history_display."SemanticModelCall" AS SELECT * FROM public."SemanticModelCall";
CREATE VIEW history_display."SemanticControl" AS SELECT * FROM public."SemanticControl";
CREATE VIEW history_display."ModelSettings" AS SELECT * FROM public."ModelSettings";
CREATE VIEW history_display."CommentReadCheckpoint" AS SELECT t.* FROM public."CommentReadCheckpoint" t WHERE NOT history_display.is_archived('CommentReadCheckpoint',t.id);
CREATE VIEW history_display."AutoReviewJob" AS SELECT t.* FROM public."AutoReviewJob" t WHERE NOT history_display.is_archived('AutoReviewJob',t.id);
CREATE VIEW history_display."CommentReviewPolicy" AS SELECT * FROM public."CommentReviewPolicy";
CREATE VIEW history_display."CommentReviewPolicyVersion" AS SELECT * FROM public."CommentReviewPolicyVersion";
CREATE VIEW history_display."ManualReviewJob" AS SELECT t.* FROM public."ManualReviewJob" t WHERE NOT history_display.is_archived('ManualReviewJob',t.id);
CREATE VIEW history_display."AutoContactRule" AS SELECT t."channels"::text::history_display."ReplyChannel"[] AS "channels",t."templateId",t."templateVersion",t."accountLimits",t."model",t."id",t."platform"::text::history_display."Platform" AS "platform",t."policyId",t."policyRevision",t."threshold",t."channel"::text::history_display."ReplyChannel" AS "channel",t."content",t."accountIds",t."enabled",t."version",t."authorizedBy",t."authorizedAt",t."authorizedHash",t."mode",t."createdAt",t."updatedAt" FROM public."AutoContactRule" t;
CREATE VIEW history_display."AutoContactControl" AS SELECT t."activeJobId",t."leaseUntil",t."platform"::text::history_display."Platform" AS "platform",t."mode",t."pauseReason",t."pausedAt" FROM public."AutoContactControl" t;
CREATE VIEW history_display."AutoContactJob" AS SELECT t."manualRequestId",t."availabilityVersion",t."sourceSnapshot",t."id",t."ruleId",t."ruleVersion",t."reviewId",t."reviewVersion",t."mode",t."platform"::text::history_display."Platform" AS "platform",t."recipientId",t."postId",t."commentId",t."channel"::text::history_display."ReplyChannel" AS "channel",t."content",t."evidence",t."eligibilityHash",t."status",t."reason",t."accountId",t."attemptId",t."leaseUntil",t."createdAt",t."updatedAt" FROM public."AutoContactJob" t WHERE NOT history_display.is_archived('AutoContactJob',t.id);
CREATE VIEW history_display."PostAvailability" AS SELECT t."platform"::text::history_display."Platform" AS "platform",t."postId",t."state",t."reason",t."version",t."checkedAt",t."source",t."evidence",t."invalidatedAt" FROM public."PostAvailability" t;
CREATE VIEW history_display."PostAvailabilityEvent" AS SELECT t."id",t."platform"::text::history_display."Platform" AS "platform",t."postId",t."version",t."state",t."reason",t."checkedAt",t."source",t."evidence",t."actorId" FROM public."PostAvailabilityEvent" t;
CREATE VIEW history_display."AutomationPreferences" AS SELECT * FROM public."AutomationPreferences";
CREATE VIEW history_display."NormalAutomationAcceptance" AS SELECT * FROM public."NormalAutomationAcceptance";
CREATE VIEW history_display."NormalAcceptancePost" AS SELECT * FROM public."NormalAcceptancePost";
CREATE VIEW history_display."ManualReplyRequest" AS SELECT * FROM public."ManualReplyRequest";
